/* @socom-skeleton stub zAnimObjectTranslateStateTick__FP14_zanim_cmd_hdrPf */
bool zAnimObjectTranslateStateTick(_zanim_cmd_hdr *header, float *)
{
	/* 0x1bd320: put the node at a point: the offset (1), or the offset from the node's own
	 * position (4), plus the anim's point argument (2); with AT_NODE the point (else the
	 * origin) is taken through that node's world transform. Flags 8/0x10/0x20 keep the
	 * node's own x/y/z. Nothing moves when there is neither a point nor an AT_NODE. */
	_zanim_cmd_translate_state* cmd = reinterpret_cast<_zanim_cmd_translate_state*>(header);
	CZAnim* anim = ZAnim.m_CurAnim;
	zdb::CNode* node = anim->GetNode(cmd->node_ref, false);
	zdb::CNode* at = anim->GetNode(cmd->at_node_ref, false);

	if (node == NULL)
		return true;

	const f32* pos = node->m_matrix.m_matrix[3];
	CPnt3D point;
	point.x = 0.0f;
	point.y = 0.0f;
	point.z = 0.0f;
	bool have = false;

	if (cmd->flags & 0x4)
	{
		point.x = pos[0] + cmd->offset[0];
		point.y = pos[1] + cmd->offset[1];
		point.z = pos[2] + cmd->offset[2];
		have = true;
	}
	else if (cmd->flags & 0x1)
	{
		point.x += cmd->offset[0];
		point.y += cmd->offset[1];
		point.z += cmd->offset[2];
		have = true;
	}

	if (cmd->flags & 0x2)
	{
		/* the anim's position argument (0x1bd408), when it has one */
		const CPnt3D* input = anim->m_arg_list != NULL ? anim->m_arg_list->GetPnt3D(CZAnimArg::ARG_POSITION) : NULL;

		if (input != NULL)
		{
			point.Add(input, &point);
			have = true;
		}
	}

	if (!have && at == NULL)
		return true;

	if (at != NULL)
		at->TransformToWorld(point);

	f32 x = (cmd->flags & 0x8) ? pos[0] : point.x;
	f32 y = (cmd->flags & 0x10) ? pos[1] : point.y;
	f32 z = (cmd->flags & 0x20) ? pos[2] : point.z;
	node->SetPosition(x, y, z);
	return true;
}

/* @socom-skeleton stub zAnimObjectRotateStateTick__FP14_zanim_cmd_hdrPf */
bool zAnimObjectRotateStateTick(_zanim_cmd_hdr *header, float *)
{
	/* 0x1bd1f0: record { header; u16 flags (+0x4); u8 node (+0x6), at node (+0x7); f32
	 * rotation[3] (+0x8) } - the node takes the AT node's world matrix (if any), then the
	 * rotation (1) or its own rotation plus the rotation (2); its position is kept */
	u8* cmd = reinterpret_cast<u8*>(header);
	u16 flags = *reinterpret_cast<u16*>(cmd + 4);
	CZAnim* anim = ZAnim.m_CurAnim;
	zdb::CNode* node = anim->GetNode(cmd[6], false);
	zdb::CNode* at = anim->GetNode(cmd[7], false);

	if (node == NULL)
		return true;

	CPnt3D rotation;
	rotation.x = 0.0f;
	rotation.y = 0.0f;
	rotation.z = 0.0f;
	f32 x = node->m_matrix.m_matrix[3][0];
	f32 y = node->m_matrix.m_matrix[3][1];
	f32 z = node->m_matrix.m_matrix[3][2];

	if (at != NULL)
	{
		CMatrix world;
		at->BuildMTW(world);
		node->SetMatrix(&world);
	}

	if (flags & 0x1)
	{
		rotation.Add(reinterpret_cast<const CPnt3D*>(cmd + 8), &rotation);
		node->SetRotation(&rotation);
	}

	if (flags & 0x2)
	{
		node->GetRotation(&rotation);
		rotation.Add(reinterpret_cast<const CPnt3D*>(cmd + 8), &rotation);
		node->SetRotation(&rotation);
	}

	node->SetPosition(x, y, z);
	return true;
}

